import {
  View,
  Text,
  Modal,
  KeyboardAvoidingView,
  TouchableOpacity,
} from 'react-native';
import React, {useEffect, useState} from 'react';
import {useTranslation} from 'react-i18next';
import styles from './styles';
import {useSafeAreaInsets} from 'react-native-safe-area-context';
import {isEmpty} from 'lodash';
import {IDocument} from '../../../../../model/interface/envelope.interface';
import TextCM from '../../../../../components/Text';
import {IcBlackLeftArrow, IconBlueClose} from '../../../../../assets/images';
import ButtonCM from '../../../../../components/Button';
import Toast from 'react-native-toast-message';
import {useDocumentServices} from '../../../../../hook/apiHook/useApi';
import TextFieldCM from '../../../../../components/TextField';

type Props = {
  data: IDocument;
  toggleModal: () => void;
  isVisible: boolean;
  onSuccess: () => void;
};

type HashTag = {
  id: number;
};
const ModalHashtagAlias = ({
  data,
  isVisible,
  toggleModal,
  onSuccess,
}: Props) => {
  const {t} = useTranslation();

  const insets = useSafeAreaInsets();

  const [aliasName, setAliasName] = useState<string>(
    data?.favorites?.aliasName || '',
  );
  const [hashTag, setHashTag] = useState<string[]>(
    data?.favorites?.hashTag || [],
  );
  const [tmpHashTag, setTmpHashTag] = useState<string>('');

  const DocumentServices = useDocumentServices();

  const onSubmit = async () => {
    const body = {
      ...data.favorites,
      aliasName: aliasName.trim(),
      hashTag,
    };

    const isNewAliasName = data?.favorites?.aliasName !== aliasName.trim();
    const isNewHashtag =
      JSON.stringify(data?.favorites?.hashTag) !== JSON.stringify(hashTag);

    if (!isNewAliasName && !isNewHashtag) {
      toggleModal();
      return;
    }
    try {
      await DocumentServices.updateFavourite(body);
      onSuccess();
      let messageSuccess = t('eContract.DC.Messages.TxtUpdateSuccessHashtagAndAlias');
      if (isNewAliasName) {
        messageSuccess = t('eContract.DC.Messages.TxtUpdateSuccessAlias');
        if (isNewHashtag) {
          messageSuccess = t('eContract.DC.Messages.TxtUpdateSuccessHashtagAndAlias');
        }
      } else if (isNewHashtag) {
        messageSuccess = t('eContract.DC.Messages.TxtUpdateSuccessHashtag');
      }
      Toast.show({
        type: 'success',
        text1: messageSuccess,
      });
    } catch (error) {
      Toast.show({
        type: 'error',
        text1: t('eContract.CM.TxtSystemError'),
      });
    } finally {
      toggleModal();
    }
  };

  const onRemoveHashtag = (index: number) => {
    const newHashTags = [...hashTag];
    newHashTags.splice(index, 1);
    setHashTag(newHashTags);
  };

  const renderItemHashtags = () => {
    if (isEmpty(hashTag)) {
      return (
        <TextCM style={styles.txtNoHashtag}>{t('eContract.DC.TxtNoHashtag')}</TextCM>
      );
    }
    return (
      <View style={styles.ctnHashtag}>
        {hashTag.map((item, index) => {
          return (
            <View style={styles.viewItemHashtag} key={index}>
              <TextCM style={styles.txtHashtag}>#{item}</TextCM>
              <TouchableOpacity onPress={() => onRemoveHashtag(index)}>
                <IconBlueClose width={12} height={12} />
              </TouchableOpacity>
            </View>
          );
        })}
      </View>
    );
  };

  const IconAddNewHashtag = () => {
    return (
      <TouchableOpacity onPress={onAddHashtagChange}>
        <TextCM style={styles.txtAdd}>{t('eContract.DC.TxtAdd')}</TextCM>
      </TouchableOpacity>
    );
  };

  const onAddHashtagChange = () => {
    if (!tmpHashTag.trim()) return;
    setHashTag([...hashTag, tmpHashTag.replace(/\s/g, '')]);
    setTmpHashTag('');
  };

  return (
    <Modal animationType="fade" transparent visible={isVisible}>
      <KeyboardAvoidingView
        style={{flex: 1}}
        behavior={'padding'}
        keyboardVerticalOffset={-insets.bottom}>
        <View style={styles.ctnContainer}>
          <View style={styles.ctnTop} onTouchEnd={toggleModal} />
          <View style={[styles.ctnContent, {paddingBottom: insets.bottom}]}>
            <View style={styles.viewHeader}>
              <TouchableOpacity onPress={toggleModal}>
                <IcBlackLeftArrow width={14} height={16} />
              </TouchableOpacity>
              <TextCM style={styles.txtTitle}>
                {t('eContract.DC.TxtHashtagAndAlias')}
              </TextCM>
              <View />
            </View>
            <View style={styles.viewBody}>
              <TextFieldCM
                label={t('eContract.DC.TxtHashtag')}
                value={tmpHashTag}
                onChangeText={setTmpHashTag}
                maxLength={100}
                viewIconRight={<IconAddNewHashtag />}
                // styleIconRight={styles.iconAddNewHashtag}
              />
              {renderItemHashtags()}
              <TextFieldCM
                label={t('eContract.DC.TxtAlias')}
                value={aliasName}
                onChangeText={setAliasName}
                maxLength={100}
              />
              <View style={styles.footer}>
                <ButtonCM
                  label={t('eContract.CM.TxtSave')}
                  onPress={onSubmit}
                  style={styles.btnFooter}
                />
              </View>
            </View>
          </View>
        </View>
      </KeyboardAvoidingView>
    </Modal>
  );
};

export default ModalHashtagAlias;
