
import React from 'react';
import {useTranslation} from 'react-i18next';
import {ScrollView} from 'react-native';
import styles from './styles';
import {isEmpty, isUndefined} from 'lodash';
import {convertObjectToArray, mapData} from './helper';
import {getListTypeLogin} from '../ModalCreateConfig/helper';
import { IConfigSecurityLogin, IHistoryConfigLogin } from '../../../../../services/interface';
import { View as ViewCM } from 'react-native';
import ButtonCM from '../../../../../components/Button';
import BottomSheetCM from '../../../../../components/BottomSheet';
import TextCM from '../../../../../components/Text';

type Props = {
  isVisible: boolean;
  onClose: () => void;
  data: IHistoryConfigLogin | null;
};

const ModalHistoryDetail = ({isVisible, onClose, data}: Props) => {
  const {t} = useTranslation();

  const Content = () => {
    const newData = mapData(data as IHistoryConfigLogin);
    return (
      <ViewCM style={styles.container}>
        <ScrollView contentContainerStyle={styles.list}>
          <InfoData
            label={
              !isEmpty(data?.cdc.previousValue)
                ? t('eContract.GS.history.infoNew')
                : t('eContract.GS.history.info')
            }
            data={newData.value}
          />
          {!isEmpty(newData.previousValue) && (
            <InfoData
              label={t('eContract.GS.history.infoOld')}
              data={newData?.previousValue}
            />
          )}
        </ScrollView>
        <ButtonCM label={t('eContract.CM.BtnClose')} onPress={onClose} />
      </ViewCM>
    );
  };

  return (
    <BottomSheetCM
      title={t('eContract.GS.history.detailHistory')}
      isVisible={isVisible}
      onClose={onClose}
      renderContent={<Content />}
      // containerStyle={{
      //   backgroundColor: 'transparent',
      // }}
    />
  );
};

export default ModalHistoryDetail;

type InfoDataProps = {
  data?: IConfigSecurityLogin;
  label: string;
};

const InfoData = ({data, label}: InfoDataProps) => {
  const {t} = useTranslation();

  return (
    <ViewCM style={styles.viewInfo}>
      <TextCM style={styles.txtTitle}>{label}</TextCM>
      <ViewCM style={styles.viewContentInfo}>
        {data?.name && (
          <ViewCM style={styles.viewItem}>
            <TextCM style={styles.txtLabel}>
              {t('eContract.GS.configSecurityLogin.TxtNameTypeLogin')}
            </TextCM>
            <TextCM style={styles.txtValue}>{data?.name}</TextCM>
          </ViewCM>
        )}
        {data?.type && (
          <ViewCM style={styles.viewItem}>
            <TextCM style={styles.txtLabel}>
              {t('eContract.GS.configSecurityLogin.TxtTypeLogin')}
            </TextCM>
            <TextCM style={styles.txtValue}>
              {getListTypeLogin().find(i => i.id === data.type)?.label}
            </TextCM>
          </ViewCM>
        )}
        {!isUndefined(data?.active) && (
          <ViewCM style={styles.viewItem}>
            <TextCM style={styles.txtLabel}>
              {t('eContract.GS.addConfigSignature.status')}
            </TextCM>
            <TextCM style={styles.txtValue}>
              {data?.active
                ? t('eContract.GS.history.active')
                : t('eContract.GS.history.nonActive')}
            </TextCM>
          </ViewCM>
        )}
        {!isEmpty(data?.attribute) && (
          <>
            <TextCM style={styles.txtLabel}>
              {t('eContract.GS.configSecurityLogin.TxtProperties')}
            </TextCM>
            <ViewCM style={styles.viewProperties}>
              {convertObjectToArray(data?.attribute)?.map(
                (item: {key: string; value: string}) => {
                  return (
                    <ViewCM style={styles.viewItemProperties} key={item.key}>
                      <TextCM style={styles.txtLabelProperties}>
                        {item.key}
                      </TextCM>
                      <TextCM
                        style={styles.txtValueProperties}
                        numberOfLines={2}>
                        {item.value}
                      </TextCM>
                    </ViewCM>
                  );
                },
              )}
            </ViewCM>
          </>
        )}
      </ViewCM>
    </ViewCM>
  );
};
