import React, {useEffect, useState} from 'react';
import {FlatList, Image, TouchableOpacity, View} from 'react-native';
import styles from './styles';
import {useTranslation} from 'react-i18next';
import {isEmpty} from 'lodash';
import TextCM from '../../../../../../../components/Text';
import {IconCheckedRadio, IconRadio} from '../../../../../../../assets/images';
import {String} from '../../../../../../../constants';
import ButtonCM from '../../../../../../../components/Button';
import {IImageSignature} from '../../interface';
import { useAccountServices } from '../../../../../../../hook/apiHook/useApi';

type Props = {
  onSave: (value: string) => void;
};

const SignatureFromAccount = ({onSave}: Props) => {
  const {t} = useTranslation();

  const [currentSignature, setCurrentSignature] =
    useState<IImageSignature | null>(null);
  const [listData, setListData] = useState<IImageSignature[]>([]);
  const accountServices = useAccountServices();
  useEffect(() => {
    getListData();
  }, []);

  const getListData = async () => {
    try {
      const params = {
        name: '',
      };
      const res = await accountServices.listImageSignature(params);
      const lsStar = res.filter(i => i.star);
      const lsUnStar = res.filter(i => !i.star);
      setListData([...lsStar, ...lsUnStar]);
      setCurrentSignature(lsStar[0]);
    } catch (error) {}
  };

  const renderItem = ({item}: {item: IImageSignature}) => {
    return (
      <TouchableOpacity
        activeOpacity={0.8}
        style={styles.ctn}
        onPress={() => setCurrentSignature(item)}>
        <View style={styles.header}>
          <TextCM style={styles.txtName} numberOfLines={1}>
            {item.name}
          </TextCM>

          {item.id === currentSignature?.id ? (
            <IconCheckedRadio width={20} height={20} />
          ) : (
            <IconRadio width={20} height={20} />
          )}
        </View>
        <View style={styles.body}>
          <Image
            style={styles.styleImage}
            source={{uri: String.PREFIX_IMG_BASE64 + item.signature}}
          />
        </View>
      </TouchableOpacity>
    );
  };

  const onContinue = () => {
    onSave(currentSignature?.signature || '');
  };

  return (
    <View style={styles.container}>
      <FlatList
        data={listData}
        showsVerticalScrollIndicator={false}
        keyExtractor={item => item.id.toString()}
        renderItem={renderItem}
        contentContainerStyle={styles.ctnFlatList}
        ListEmptyComponent={<Nodata />}
      />
      <View style={styles.footer}>
        <ButtonCM
          label={t('eContract.CM.BtnContinue')}
          onPress={onContinue}
          disabled={isEmpty(currentSignature?.signature)}
        />
      </View>
    </View>
  );
};

export default SignatureFromAccount;

const Nodata = () => {
  const {t} = useTranslation();

  return (
    <View style={styles.viewNodata}>
      <TextCM style={styles.txtTitleNodata}>{t('eContract.NT.TxtNoSign')}</TextCM>
      <TextCM style={styles.txtDesNodata}>{t('eContract.NT.TxtDesNoSign')}</TextCM>
    </View>
  );
};
