import {create} from 'zustand';
import {
  IOrganization,
  ITsaConfig,
  Party,
} from '../../../model/interface/envelope.interface';
import {ItemType, MainItemType} from '../components/CustomDrawerContent/helper';

export const ListTSAConfig = [
  {
    label: 'CDS.fptTsa',
    value: 'fptTsa',
  },
];

interface DocumentState {
  currentFocused: ItemType;
  mainCurrentFocused: MainItemType;
  mainArrayCurrentFocused: any[];
  reloadData: number;
  isShowModalOrganization: boolean;
  currentFocusOrganization: IOrganization | null;
  isDueDateStatus: boolean;
  itemTopRelatedDocument: any;
  itemBottomRelatedDocument: any[];
  itemInformationDocument: any[];
  dataListTsaConfigSelected: any;
  listTsaConfigSelected: ITsaConfig[];
  partySelectFromFlowTemplate: Party;
  userSelectFromFlowTemplate: any;

  updateCurrentFocused: (payload: any) => void;
  updateMainCurrentFocused: (payload: any) => void;
  updateArrayMainCurrentFocused: (payload: any) => void;
  reloadDataFn: () => void;
  showSortOrganization: (payload: any) => void;
  setCurrentOrganization: (payload: any) => void;
  setItemTopRelatedDocument: (payload: any) => void;
  setItemBottomRelatedDocument: (payload: any[] | null) => void;
  removeItemBottomRelatedDocument: (payload: any) => void;
  setItemInformationDocument: (payload: any) => void;
  updateIsDueDateStatus: (payload: boolean) => void;
  updateDataListTsaConfigSelected: (payload: any) => void;
  updateListTsaConfigSelected: (payload: ITsaConfig[]) => void;
  setPartySelectFromFlowTemplate: (payload: Party) => void;
  setUserSelectFromFlowTemplate: (payload: any) => void;
}

const initialState = {
  currentFocused: ItemType.Inprogress,
  mainCurrentFocused: MainItemType.MainDocument,
  mainArrayCurrentFocused: ['mainDocument'],
  reloadData: 0,
  isShowModalOrganization: false,
  currentFocusOrganization: null,
  isDueDateStatus: false,
  itemTopRelatedDocument: null,
  itemBottomRelatedDocument: [],
  itemInformationDocument: [],
  dataListTsaConfigSelected: [],
  listTsaConfigSelected: ListTSAConfig,
  partySelectFromFlowTemplate: {} as Party,
  userSelectFromFlowTemplate: {},
};

export const useDocumentStore = create<DocumentState>()(set => ({
  ...initialState,

  updateCurrentFocused: payload =>
    set(state => ({
      ...state,
      currentFocused: payload,
      isDueDateStatus:
        payload !== ItemType.Inprogress ? false : state.isDueDateStatus,
    })),

  updateMainCurrentFocused: payload =>
    set(state => ({...state, mainCurrentFocused: payload})),

  updateArrayMainCurrentFocused: payload =>
    set(state => {
      const index = state.mainArrayCurrentFocused.indexOf(payload);
      return {
        ...state,
        mainArrayCurrentFocused:
          index === -1
            ? [...state.mainArrayCurrentFocused, payload]
            : state.mainArrayCurrentFocused.filter(item => item !== payload),
      };
    }),

  reloadDataFn: () =>
    set(state => ({...state, reloadData: state.reloadData + 1})),

  showSortOrganization: payload => set({isShowModalOrganization: payload}),

  setCurrentOrganization: payload => set({currentFocusOrganization: payload}),

  setItemTopRelatedDocument: payload => set({itemTopRelatedDocument: payload}),

  setItemBottomRelatedDocument: payload =>
    set(state => {
      if (payload === null) return {itemBottomRelatedDocument: []};
      return {
        ...state,
        itemBottomRelatedDocument: [
          ...state.itemBottomRelatedDocument,
          ...payload,
        ],
      };
    }),

  removeItemBottomRelatedDocument: payload =>
    set(state => ({
      ...state,
      itemBottomRelatedDocument: state.itemBottomRelatedDocument.filter(
        val => val.id !== payload.id,
      ),
    })),

  setItemInformationDocument: payload =>
    set(state => {
      if (payload === null) return {itemInformationDocument: []};
      const exists = state.itemInformationDocument.some(
        item => item.id === payload.id,
      );
      return {
        ...state,
        itemInformationDocument: exists
          ? state.itemInformationDocument.filter(item => item.id !== payload.id)
          : [...state.itemInformationDocument, payload],
      };
    }),

  updateIsDueDateStatus: payload => set({isDueDateStatus: payload}),

  updateDataListTsaConfigSelected: payload =>
    set({dataListTsaConfigSelected: payload}),

  updateListTsaConfigSelected: payload => set({listTsaConfigSelected: payload}),

  setPartySelectFromFlowTemplate: payload =>
    set({partySelectFromFlowTemplate: payload}),

  setUserSelectFromFlowTemplate: payload =>
    set({userSelectFromFlowTemplate: payload}),
}));
