import {View, TouchableOpacity} from 'react-native';
import React, {useEffect, useState} from 'react';
import styles from './styles';
import {useTranslation} from 'react-i18next';
import {isEmpty} from 'lodash';
import {useNavigation} from '@react-navigation/native';
import {
  IDocument,
  IOrganization,
} from '../../../../../model/interface/envelope.interface';
import {
  getListItem,
  ItemType,
  MainItemType,
} from '../../../../../navigation/SideMenu/components/CustomDrawerContent/helper';
import {DateUtils} from '../../../../../utils';
import {
  IconMenuFavorite,
  IconMenuFavoriteActive,
  IconRedWarning,
} from '../../../../../assets/images';
import {NavigationName} from '../../../../../constants';
import TextCM from '../../../../../components/Text';
import Toast from 'react-native-toast-message';
import {useDocumentStore} from '../../../../../navigation/SideMenu/store/app-store';
import {useDocumentServices} from '../../../../../hook/apiHook/useApi';

type Props = {
  data: IDocument & IOrganization;
  // data: any;
};
const DocumentItem = ({data}: Props) => {
  const {t} = useTranslation();
  const navigation = useNavigation<any>();

  const {currentFocused, mainCurrentFocused} = useDocumentStore();

  const [favorites, setFavorites] = useState(data.favorites);

  const DocumentServices = useDocumentServices();

  useEffect(() => {
    setFavorites(data.favorites);
  }, [data.favorites]);

  const onPressFavorite = async () => {
    if (favorites) {
      try {
        await DocumentServices.removeFavourite(data.id);
        setFavorites(null);
      } catch (error) {
        showError();
      }
    } else {
      onSaveFavorite();
    }
  };

  const onSaveFavorite = async () => {
    const body = {
      aliasName: null,
      createdBy: null,
      createdDate: null,
      custId: data.custId,
      hashTag: null,
      id: null,
      lastModifiedBy: null,
      lastModifiedDate: null,
      orgIn: data.orgIn,
      personal: data.owner,
      resourceId: data.id,
      resourceType: 'e',
    };
    try {
      await DocumentServices.updateFavourite(body);
      setFavorites(body);
    } catch (error) {
      showError();
    }
  };

  const showError = () => {
    Toast.show({
      type: 'error',
      text1: t('eContract.CM.TxtSystemError'),
    });
  };

  const getNameDateCreate = () => {
    if (
      currentFocused === ItemType.CCDocument ||
      currentFocused === ItemType.Favorite ||
      currentFocused === ItemType.SignFlow
    ) {
      return t('eContract.DC.TxtCreateDate');
    }
    switch (data.status) {
      case ItemType.Done:
        return t('eContract.DC.TxtDoneDate');
      default:
        return t('eContract.DC.TxtCreateDate');
    }
  };

  const getDataDateCreate = () => {
    if (currentFocused === ItemType.Favorite) {
      return DateUtils.convertDateToDDMMYYYYhhmm(data.createdDate);
    }
    switch (data.status) {
      case ItemType.Done:
      case ItemType.SignFlow:
        return DateUtils.convertDateToDDMMYYYYhhmm(data.flowFinishDate);
      default:
        return DateUtils.convertDateToDDMMYYYYhhmm(data.createdDate);
    }
  };

  const getNameDateSign = () => {
    switch (currentFocused) {
      case ItemType.InprogressDocumentOrganization:
      case ItemType.DoneDocumentOrganization:
        return t('eContract.DC.TxtSignDate');
      case ItemType.CancelDocumentOrganization:
        return t('eContract.DC.TxtCancelDate');
      case ItemType.RejectDocumentOrganization:
        return t('eContract.DC.TxtRejectDate');
      case ItemType.ExpiredDocumentOrganization:
        return t('eContract.DC.TxtExpiredDate');
      default:
        return t('eContract.DC.TxtExpirationDate');
    }
  };
  const getDataDateSign = () => {
    switch (currentFocused) {
      case ItemType.InprogressDocumentOrganization:
      case ItemType.DoneDocumentOrganization:
        return DateUtils.convertDateToDDMMYYYY(data.signDate) || '---';
      case ItemType.CancelDocumentOrganization:
      case ItemType.RejectDocumentOrganization:
        return DateUtils.convertDateToDDMMYYYY(data.lastModifiedDate) || '---';
      case ItemType.ExpiredDocumentOrganization:
        return DateUtils.convertDateToDDMMYYYY(data.flowFinishDate) || '---';
      default:
        return DateUtils.convertDateToDDMMYYYY(
          DateUtils.addDays(data.createdDate, data.dueInDays),
        );
    }
  };

  const getTitleExpirationDate = () => {
    if (
      currentFocused === ItemType.CCDocument ||
      currentFocused === ItemType.Favorite
    ) {
      return t('eContract.DC.TxtExpirationDate');
    }

    switch (data.status) {
      case ItemType.Done:
        return t('eContract.DC.TxtSignDate');
      case ItemType.Cancel:
        return t('eContract.DC.TxtCancelDate');
      case ItemType.Reject:
        return t('eContract.DC.TxtRejectDate');
      case ItemType.Expired:
      case ItemType.Trash:
        return t('eContract.DC.TxtExpiredDate');
      default:
        return t('eContract.DC.TxtExpirationDate');
    }
  };

  const getDataExpirationDate = () => {
    if (
      currentFocused === ItemType.CCDocument ||
      currentFocused === ItemType.Favorite
    ) {
      return DateUtils.convertDateToDDMMYYYY(
        DateUtils.addDays(data.createdDate, data.dueInDays),
      );
    }
    switch (data.status) {
      case ItemType.Done:
      case ItemType.SignFlow:
        return DateUtils.convertDateToDDMMYYYY(data.signDate) || '---';
      case ItemType.Cancel:
      case ItemType.Reject:
      case ItemType.Trash:
        return DateUtils.convertDateToDDMMYYYY(data.lastModifiedDate) || '---';
      case ItemType.Expired:
        return DateUtils.convertDateToDDMMYYYY(data.flowFinishDate) || '---';
      default:
        return DateUtils.convertDateToDDMMYYYY(
          DateUtils.addDays(data.createdDate, data.dueInDays),
        );
    }
  };

  const getNameUserCreate = () => {
    if (currentFocused === ItemType.SignFlow) {
      return data.owner;
    }
    return '';
  };

  const onPressDocument = () => {
    const newData = {
      ...data,
      type: currentFocused,
    };
    navigation.navigate(NavigationName.DocumentDetailScreen, {
      data: newData,
    });
  };

  const getNameFavorite = () => {
    const item = getListItem(t).find(item => item.type === data.status);
    return item;
  };

  const checkShowFavorite = () => {
    if (
      currentFocused === ItemType.Draft ||
      currentFocused === ItemType.Trash ||
      currentFocused === ItemType.InprogressDocumentOrganization ||
      currentFocused === ItemType.DoneDocumentOrganization ||
      currentFocused === ItemType.CancelDocumentOrganization ||
      currentFocused === ItemType.RejectDocumentOrganization ||
      currentFocused === ItemType.ExpiredDocumentOrganization
    ) {
      return false;
    }
    return true;
  };

  const getNameAlias = () => {
    if (currentFocused === ItemType.Favorite && data.favorites?.aliasName) {
      return `(${data.favorites?.aliasName})`;
    }
    return '';
  };

  const getNameHashtags = () => {
    if (currentFocused === ItemType.Favorite && data.favorites?.hashTag) {
      return data.favorites.hashTag
        .map((hashtag: any) => `#${hashtag}`)
        .join(', ');
    }
    return '';
  };

  const renderWarning = () => {
    if (currentFocused === ItemType.Inprogress && checkShowWarning()) {
      return (
        <View style={styles.viewIconWarning}>
          <IconRedWarning width={16} height={16} />
        </View>
      );
    }
    return null;
  };

  const checkShowWarning = () => {
    const currentDate = new Date();
    const startDate = DateUtils.addDays(data.createdDate, data.dueInDays - 2);
    const endDate = DateUtils.addDays(data.createdDate, data.dueInDays + 4);
    return (
      currentDate.getTime() >= startDate.getTime() &&
      currentDate.getTime() <= endDate.getTime()
    );
  };

  const validateCurrenOrganization = () => {
    return (
      currentFocused === ItemType.InprogressDocumentOrganization ||
      currentFocused === ItemType.DoneDocumentOrganization ||
      currentFocused === ItemType.CancelDocumentOrganization ||
      currentFocused === ItemType.RejectDocumentOrganization ||
      currentFocused === ItemType.ExpiredDocumentOrganization
    );
  };

  const validateDocumentOrganization = () => {
    if (mainCurrentFocused === MainItemType.MainDocumentOrganization) {
      if (validateCurrenOrganization()) {
        return true;
      } else {
        return false;
      }
    } else {
      if (validateCurrenOrganization()) {
        return true;
      } else {
        return false;
      }
    }
  };

  const validateExpirationDate = () => {
    if (mainCurrentFocused !== MainItemType.MainDocumentOrganization) {
      if (validateCurrenOrganization()) {
        return false;
      } else {
        return true;
      }
    } else {
      if (
        currentFocused === ItemType.Inprogress ||
        currentFocused === ItemType.Done ||
        currentFocused === ItemType.Cancel ||
        currentFocused === ItemType.Reject ||
        currentFocused === ItemType.Expired ||
        currentFocused === ItemType.SignFlow ||
        currentFocused === ItemType.Trash ||
        currentFocused === ItemType.CCDocument ||
        currentFocused === ItemType.Favorite ||
        currentFocused === ItemType.Authen
      ) {
        return true;
      } else {
        false;
      }
    }
  };

  return (
    <TouchableOpacity style={styles.container} onPress={onPressDocument}>
      <View style={styles.header}>
        {renderWarning()}
        <View style={styles.viewTitle}>
          <TextCM
            style={[
              styles.txtTitle,
              data.disableDocument &&
                mainCurrentFocused === MainItemType.MainDocument &&
                styles.txtRed,
            ]}>
            {data.name.trim()}
          </TextCM>
          {!isEmpty(getNameAlias()) && (
            <TextCM style={styles.txtAlias}>{getNameAlias()}</TextCM>
          )}
        </View>
        {checkShowFavorite() && (
          <TouchableOpacity onPress={onPressFavorite}>
            {!isEmpty(favorites) ? (
              <IconMenuFavoriteActive width={16} height={16} />
            ) : (
              <IconMenuFavorite width={16} height={16} />
            )}
          </TouchableOpacity>
        )}
      </View>
      <View style={styles.viewCode}>
        <TextCM style={styles.txtCode}>{data.envNo || '---'}</TextCM>
        {currentFocused === ItemType.Favorite && (
          <TextCM
            style={[
              styles.txtStatus,
              {
                color: getNameFavorite()?.textColor,
              },
            ]}>
            • {getNameFavorite()?.title}
          </TextCM>
        )}
      </View>
      <View style={styles.viewList}>
        {getNameUserCreate() && (
          <View style={styles.viewItem}>
            <TextCM style={styles.txtName}>{t('eContract.DC.TxtUserCreate')}</TextCM>
            <TextCM style={styles.txtValue}>{getNameUserCreate()}</TextCM>
          </View>
        )}
        {getNameHashtags() && (
          <View style={styles.viewItem}>
            <TextCM style={styles.txtName}>{t('eContract.DC.TxtHashtag')}</TextCM>
            <TextCM style={styles.txtValueHashtag}>{getNameHashtags()}</TextCM>
          </View>
        )}
        {validateDocumentOrganization() && (
          <View style={styles.viewItem}>
            <TextCM style={styles.txtName}>{t('eContract.DC.TxtUserCreate')}</TextCM>
            <TextCM style={styles.txtValue}>{data.createdBy}</TextCM>
          </View>
        )}
        <View style={styles.viewItem}>
          <TextCM style={styles.txtName}>{getNameDateCreate()}</TextCM>
          <TextCM style={styles.txtValue}>{getDataDateCreate()}</TextCM>
        </View>
        {validateDocumentOrganization() && (
          <View style={styles.viewItem}>
            <TextCM style={styles.txtName}>{getNameDateSign()}</TextCM>
            <TextCM style={styles.txtValue}>{getDataDateSign()}</TextCM>
          </View>
        )}
        {data.status !== ItemType.Draft && validateExpirationDate() && (
          <View style={styles.viewItem}>
            <TextCM style={styles.txtName}>{getTitleExpirationDate()}</TextCM>
            <TextCM style={styles.txtValue}>{getDataExpirationDate()}</TextCM>
          </View>
        )}
        <View style={styles.viewItem}>
          <TextCM style={styles.txtName}>{t('eContract.DC.TxtParties')}</TextCM>
          <View style={styles.viewValueParties}>
            {!isEmpty(data?.parties) ? (
              data?.parties?.map((item: any, index: number) => {
                return (
                  <TextCM style={styles.txtValue} key={item.id}>
                    {item.type !== 'individual'
                      ? item.name || '---'
                      : item.recipients?.[0]?.contact?.name}
                  </TextCM>
                );
              })
            ) : (
              <TextCM style={styles.txtValue}>---</TextCM>
            )}
          </View>
        </View>
      </View>
    </TouchableOpacity>
  );
};

export default DocumentItem;
