import React, {useRef, useState} from 'react';
import {useTranslation} from 'react-i18next';
import {Alert, TouchableOpacity} from 'react-native';
import styles from './styles';
import TextFieldCM from '../../../../../components/TextField';
import { SizeDP } from '../../../../../constants/Size';
import ButtonCM from '../../../../../components/Button';
import { View as ViewCM } from 'react-native';
import TextCM from '../../../../../components/Text';
import { IconBlueBorderPlus, IconGreyMinus, IconRedMinus } from '../../../../../assets/images';
import BottomSheetCM from '../../../../../components/BottomSheet';

interface Props {
  onPressMinus: () => void;
  onPressPlus: () => void;
  onPressSetData: (data: number) => void;
  value: number;
  label?: string;
  attention?: string;
  min: number;
  max: number;
}

const CounterItem = ({
  onPressMinus,
  value,
  onPressPlus,
  label,
  attention,
  min,
  max,
  onPressSetData,
}: Props) => {
  const {t} = useTranslation();
  const timerAddOne = useRef<any>(null);
  const timerMinusOne = useRef<any>(null);
  const [isVisible, setIsVisiable] = useState<boolean>(false);
  const [valueInput, setValueInput] = useState<string>(value.toString());

  const addOne = () => {
    onPressPlus();
    if (timerAddOne.current) clearTimeout(timerAddOne.current!);
    timerAddOne.current = setTimeout(addOne, 100);
  };

  const minusOne = () => {
    onPressMinus();
    if (timerAddOne.current) clearTimeout(timerAddOne.current!);
    timerAddOne.current = setTimeout(minusOne, 100);
  };

  const stopTimer = () => {
    clearTimeout(timerAddOne.current);
    clearTimeout(timerMinusOne.current);
  };

  const handleSubMitValueSelect = () => {
    const num = parseInt(valueInput);
    if (isNaN(num) || num < min || num > max) {
      Alert.alert(t('eContract.CM.InvalidNumber', {min, max}));
      return;
    }
    onPressSetData(num);
    setIsVisiable(false);
  };

  const renderItem = () => {
    return (
      <ViewCM style={{rowGap: SizeDP(10)}}>
        <TextFieldCM
          keyboardType="numeric"
          value={valueInput}
          onChangeText={setValueInput}
          label={t('eContract.CM.typeText')}
        />
        <ButtonCM
          label={t('eContract.CM.BtnConfirm')}
          onPress={handleSubMitValueSelect}
        />
      </ViewCM>
    );
  };

  return (
    <>
      <ViewCM style={styles.ctn}>
        {label && <TextCM style={styles.txtLabel}>{label}</TextCM>}
        <ViewCM style={styles.item}>
          <TouchableOpacity onPressIn={minusOne} onPressOut={stopTimer}>
            {value === min ? (
              <IconGreyMinus width={SizeDP(24)} height={SizeDP(24)} />
            ) : (
              <IconRedMinus width={SizeDP(24)} height={SizeDP(24)} />
            )}
          </TouchableOpacity>
          <TouchableOpacity
            hitSlop={SizeDP(15)}
            onPress={() => setIsVisiable(true)}>
            <TextCM>{value}</TextCM>
          </TouchableOpacity>
          <TouchableOpacity onPressIn={addOne} onPressOut={stopTimer}>
            {value === max ? (
              <IconGreyMinus width={SizeDP(24)} height={SizeDP(24)} />
            ) : (
              <IconBlueBorderPlus width={SizeDP(24)} height={SizeDP(24)} />
            )}
          </TouchableOpacity>
        </ViewCM>
        {attention && <TextCM style={styles.txtAttention}>{attention}</TextCM>}
      </ViewCM>

      <BottomSheetCM
        title={t('eContract.CM.typeText')}
        isVisible={isVisible}
        onClose={() => {
          setIsVisiable(false);
          setValueInput(value.toString());
        }}
        renderContent={renderItem()}
        withKeyboardAvoidingView={true}
      />
    </>
  );
};

export default CounterItem;
