import {ItemType} from '../../../../../../../navigation/SideMenu/components/CustomDrawerContent/helper';

export const getDataSortDate = (type: ItemType) => {
  switch (type) {
    case ItemType.Draft:
      return [
        {
          id: 'createdDate,desc',
          label: 'eContract.DC.modal.TxtCreateRecent',
        },
        {
          id: 'createdDate,asc',
          label: 'eContract.DC.modal.TxtCreateOldest',
        },
      ];
    case ItemType.Done:

    case ItemType.DoneDocumentOrganization:
      return [
        {
          id: 'lastModifiedDate,desc',
          label: 'eContract.DC.modal.TxtDoneRecent',
        },
        {
          id: 'signDate,desc',
          label: 'eContract.DC.modal.TxtSignRecent',
        },
        {
          id: 'lastModifiedDate,asc',
          label: 'eContract.DC.modal.TxtDoneOldest',
        },
        {
          id: 'signDate,asc',
          label: 'eContract.DC.modal.TxtSignOldest',
        },
      ];
    case ItemType.Cancel:
      return [
        {
          id: 'createdDate,desc',
          label: 'eContract.DC.modal.TxtCreateRecent',
        },
        {
          id: 'lastModifiedDate,desc',
          label: 'eContract.DC.modal.TxtCancelRecent',
        },
        {
          id: 'createdDate,asc',
          label: 'eContract.DC.modal.TxtCreateOldest',
        },
        {
          id: 'lastModifiedDate,asc',
          label: 'eContract.DC.modal.TxtCancelOldest',
        },
      ];
    case ItemType.Reject:
      return [
        {
          id: 'createdDate,desc',
          label: 'eContract.DC.modal.TxtCreateRecent',
        },
        {
          id: 'lastModifiedDate,desc',
          label: 'eContract.DC.modal.TxtRejectRecent',
        },
        {
          id: 'createdDate,asc',
          label: 'eContract.DC.modal.TxtCreateOldest',
        },
        {
          id: 'lastModifiedDate,asc',
          label: 'eContract.DC.modal.TxtRejectOldest',
        },
      ];
    case ItemType.Expired:
    case ItemType.Trash:
      return [
        {
          id: 'createdDate,desc',
          label: 'eContract.DC.modal.TxtCreateRecent',
        },
        {
          id: 'lastModifiedDate,desc',
          label: 'eContract.DC.modal.TxtExpiredRecent',
        },
        {
          id: 'createdDate,asc',
          label: 'eContract.DC.modal.TxtCreateOldest',
        },
        {
          id: 'lastModifiedDate,asc',
          label: 'eContract.DC.modal.TxtExpiredOldest',
        },
      ];
    case ItemType.Inprogress:
    case ItemType.SignFlow:
    case ItemType.CCDocument:
    case ItemType.Favorite:
    case ItemType.ExpiredDocumentOrganization:
    case ItemType.RejectDocumentOrganization:
    case ItemType.InprogressDocumentOrganization:
    case ItemType.CancelDocumentOrganization:
    case ItemType.Authen:
      return [
        {
          id: 'createdDate,desc',
          label: 'eContract.DC.modal.TxtCreateRecent',
        },
        {
          id: 'signDate,desc',
          label: 'eContract.DC.modal.TxtSignRecent',
        },
        {
          id: 'createdDate,asc',
          label: 'eContract.DC.modal.TxtCreateOldest',
        },
        {
          id: 'signDate,asc',
          label: 'eContract.DC.modal.TxtSignOldest',
        },
      ];
  }
};
