import React, {useState} from 'react';
import {useTranslation} from 'react-i18next';
import {Image, Modal, TouchableOpacity} from 'react-native';
import {useSafeAreaInsets} from 'react-native-safe-area-context';
import styles from './styles';
import {useAppDispatch, useAppSelector} from '../../../../hook/useRedux';
import {accountActions} from '../../../../redux/slices';
import TextCM from '../../../../components/Text';
import {View as ViewCM} from 'react-native';
import {IconAvatarDefault, IconBlackLeftArrow} from '../../../../assets/images';
import {ScreenWidth, SizeDP} from '../../../../constants/Size';
import {String} from '../../../../constants';
import ButtonCM from '../../../../components/Button';
import ModalConfirm from '../../../../components/ModalConfirm';
import ImageCropPicker from '../../../../components/ImageCropPicker';
import Toast from 'react-native-toast-message';
import { useAccountServices } from '../../../../hook/apiHook/useApi';

type Props = {
  onClose: () => void;
  isVisible: boolean;
};

const ModalUpdateAvatar = ({onClose, isVisible}: Props) => {
  const {t} = useTranslation();
  const dispatch = useAppDispatch();
  const user = useAppSelector(state => state.account.dataAccount);

  const [isVisibleDelete, setIsVisibleDelete] = useState(false);
  const [isLoadingAvatar, setIsLoadingAvatar] = useState(false);

  const insets = useSafeAreaInsets();
  const accountServices = useAccountServices();

  const onPressUploadAvatar = () => {
    setIsLoadingAvatar(true);
    ImageCropPicker.ChoosePhoto().then((result: any) => {
      if (result) {
        const path = result.path;
        onUpdateAvatar(path);
      }
    });
  };

  const onUpdateAvatar = async (path: string) => {
    try {
      const body = new FormData();
      body.append('file', {
        uri: path,
        type: 'image/jpeg',
        name: 'avatar.jpg',
      } as any);
      const data = await accountServices.postUpdateAvatar(body);
      Toast.show({
        text1: t('eContract.AI.messageValidate.updateSuccess'),
        type: 'success',
      }); 
      dispatch(accountActions.fetchAccount());
    } catch (error) {
      Toast.show({
        type: 'error',
        text1: t('eContract.CM.TxtSystemError'),
      });
    } finally {
      onClose();
      setIsLoadingAvatar(false);
    }
  };

  const onPressRemoveAvatar = () => {
    toggleVisibleDelete();
  };

  const toggleVisibleDelete = () => {
    setIsVisibleDelete(!isVisibleDelete);
  };

  const onDeleteAvatar = async () => {
    toggleVisibleDelete();
    onClose();
    try {
      const data = await accountServices.deleteAvatar();
      Toast.show({
        type: 'success',
        text1: t('eContract.AI.messageValidate.deleteAvatarSuccess'),
      });
      dispatch(accountActions.fetchAccount());
    } catch (error) {
      Toast.show({
        type: 'error',
        text1: t('eContract.CM.TxtSystemError'),
      });
    } finally {
    }
  };

  return (
    <Modal animationType="fade" transparent visible={isVisible}>
      <ViewCM style={styles.ctnContainer}>
        <ViewCM style={styles.ctnTop} onTouchEnd={onClose} />
        <ViewCM style={[styles.ctnContent, {paddingBottom: insets.bottom}]}>
          <ViewCM style={styles.viewHeader}>
            <TouchableOpacity onPress={onClose}>
              <IconBlackLeftArrow width={SizeDP(14)} height={SizeDP(16)} />
            </TouchableOpacity>
            <TextCM style={styles.txtTitle}>{t('eContract.AI.TxtUpdateAvatar')}</TextCM>
            <ViewCM />
          </ViewCM>
          <ViewCM style={styles.viewBody}>
            {user.avatar ? (
              <Image
                style={styles.image}
                source={{
                  uri: String.PREFIX_IMG_BASE64 + user.avatar,
                }}
              />
            ) : (
              <ViewCM style={[styles.image, styles.viewNoAvatar]}>
                <IconAvatarDefault
                  width={ScreenWidth / 2}
                  height={ScreenWidth / 2}
                />
              </ViewCM>
            )}
            {user.avatar ? (
              <ViewCM style={styles.viewBtn}>
                <ButtonCM
                  type="white"
                  label={t('eContract.AI.TxtRemoveAvatar')}
                  onPress={onPressRemoveAvatar}
                  style={styles.btn}
                  loading={isLoadingAvatar}
                />
                <ButtonCM
                  label={t('eContract.AI.TxtChangeAvatar')}
                  onPress={onPressUploadAvatar}
                  style={styles.btn}
                  loading={isLoadingAvatar}
                />
              </ViewCM>
            ) : (
              <ViewCM style={styles.viewBtn}>
                <ButtonCM
                  label={t('eContract.AI.TxtUploadAvatar')}
                  onPress={onPressUploadAvatar}
                  style={styles.btn}
                />
              </ViewCM>
            )}
          </ViewCM>
        </ViewCM>
      </ViewCM>
      <ModalConfirm
        onClose={toggleVisibleDelete}
        onConfirm={onDeleteAvatar}
        isVisible={isVisibleDelete}
        title={t('eContract.AI.TxtTitleConfirmDelete')}
        content={t('eContract.AI.TxtContentRemoveAvatar')}
      />
    </Modal>
  );
};

export default ModalUpdateAvatar;
