import {View} from 'react-native';
import styles from '../../styles';
import React, {Dispatch, FC, SetStateAction} from 'react';
import {useTranslation} from 'react-i18next';
import TextCM from '../../../../components/Text';
import { SizeDP } from '../../../../constants/Size';
import Slider from '../../../../components/Slider';

type Props = {
  data: number;
  defaultValue: number;
  onChangeData: Dispatch<SetStateAction<number>>;
  type: 'width' | 'height';
};

const ConfigSize: FC<Props> = ({onChangeData, data, type, defaultValue}) => {
  const {t} = useTranslation();
  return (
    <View style={styles.ctnConfigList}>
      <TextCM style={styles.textConfig}>
        {type === 'width' ? t('eContract.AC.width') : t('eContract.AC.height')}
      </TextCM>
      <View style={styles.ctnWithArrow}>
        <Slider
          sliderWidth={SizeDP(120)}
          min={0}
          max={500}
          step={1}
          onValueChange={onChangeData}
          defaultValue={defaultValue}
        />
        <TextCM
          style={[
            styles.colorTextSelect,
            {width: SizeDP(28), marginLeft: SizeDP(15)},
          ]}>
          {data}
        </TextCM>
      </View>
    </View>
  );
};

export default ConfigSize;
