export const getDataTemplatesExcel = (dataTemplate: any) => {
  var fields: any =
    dataTemplate?.header?.fields
      .filter((i: any) => i.id !== 'envSubmittedFrom')
      .map((item: any) => {
        if (item.type === 'Date') {
          return {
            ...item,
            value: DateUtils.convertDateToDDMMYYYY(item.value),
          };
        }
        return item;
      }) || [];
  fields = convertDataExcel(fields);
  const parties = convertDataPartiesExcel(dataTemplate?.parties || []);

  var fieldsRequester: any = dataTemplate?.requester?.fields.filter(
    (item: any) => {
      if (
        (item.type === 'information' && isEmpty(item.recipientId)) ||
        item.type === 'text' ||
        (item.type === 'currency' && isEmpty(item.recipientId))
      ) {
        return true;
      }
      return false;
    },
  );
  fieldsRequester = convertDataExcel(fieldsRequester);

  return convertData({...fields, ...fieldsRequester, ...parties});
};

const convertData = (input: any) => {
  // Get all keys from the input object
  const keys = Object.keys(input);

  // Create the header row
  const header: any = {};
  keys.forEach((key, index) => {
    if (index < listNameColumnExcel.length) {
      header[listNameColumnExcel[index]] = key;
    }
  });

  // Create the data row
  const dataRow: any = {};
  keys.forEach((key, index) => {
    if (index < listNameColumnExcel.length) {
      dataRow[listNameColumnExcel[index]] = input[key];
    }
  });

  return [header, dataRow];
};

