import {useRoute} from '@react-navigation/native';
import React, {useEffect, useState} from 'react';
import {useTranslation} from 'react-i18next';
import {ScrollView, TouchableOpacity, View} from 'react-native';
import {SafeAreaView} from 'react-native-safe-area-context';
import ModadlHistoryRecipient from './components/ModalHistoryRecipients';
import ModalNotificationRecipient from './components/ModalNotificationRecipient';
import ModalReason from './components/ModalReason';
import ModalReplaceRecipient from './components/ModalReplaceRecipient';
import {
  IExtendedRecipients,
  getListRecipient,
  mappingShowHideAction,
} from './helper';
import styles from './styles';
import ModalIntuitiveSigning from './components/ModalIntuitiveSigning';
import {IDocument, IParties} from '../../../model/interface/envelope.interface';
import {useDocumentServices} from '../../../hook/apiHook/useApi';
import {
  convertHistoryStatus,
  mappingColorDocumentStatus,
  mappingColorHistoryStatus,
  mappingDocumentStatusToText,
  mappingRecipientToText,
} from '../helper';
import TextCM from '../../../components/Text';
import {Font} from '../../../constants';
import {
  IconBlueEdit,
  IconBlueListSigned,
  IconBlueRing,
  IconCreateDate,
  IconGreyDocumentUser,
  IconGreyStatus,
} from '../../../assets/images';
import HeaderCM from '../../../components/Header/HeaderCM';
import {ItemType} from '../../../navigation/SideMenu/components/CustomDrawerContent/helper';
import {DateUtils} from '../../../utils';

const DocumentHistory = () => {
  const route = useRoute<any>();
  const {id}: IDocument = route.params.data;
  const isCoordination = route.params.isCoordination || false;
  const {t} = useTranslation();

  const DocumentServices = useDocumentServices();

  const [showModal, setShowModal] = useState({
    modalReason: false,
    modalHistoryRecipient: false,
    modalReplaceRecipient: false,
    modalNotificationRecipient: false,
    modalIntuitiveSigning: false,
  });

  const [data, setData] = useState<any>({name: '', parties: [], id: ''});
  const [recipient, setRecipient] = useState<IExtendedRecipients | undefined>(
    undefined,
  );

  const fetchData = async () => {
    try {
      const res = await DocumentServices.getEnvelopeDetailById(id);
      setData(res);
    } catch (error) {}
  };

  useEffect(() => {
    fetchData();
  }, []);

  const toggleModal = (modalName: string) => () => {
    switch (modalName) {
      case 'modalReason':
        setShowModal({...showModal, modalReason: !showModal.modalReason});
        break;
      case 'modalHistoryRecipient':
        setShowModal({
          ...showModal,
          modalHistoryRecipient: !showModal.modalHistoryRecipient,
        });
        break;
      case 'modalReplaceRecipient':
        setShowModal({
          ...showModal,
          modalReplaceRecipient: !showModal.modalReplaceRecipient,
        });
        break;
      case 'modalNotificationRecipient':
        setShowModal({
          ...showModal,
          modalNotificationRecipient: !showModal.modalNotificationRecipient,
        });
        break;
      case 'modalIntuitiveSigning':
        setShowModal({
          ...showModal,
          modalIntuitiveSigning: !showModal.modalIntuitiveSigning,
        });
        break;
      default:
        break;
    }
  };

  const onPressRecipient = (item: IExtendedRecipients) => () => {
    setRecipient(item);
    toggleModal('modalHistoryRecipient')();
  };

  const onPressReplaceRecipient = (item: IExtendedRecipients) => () => {
    setRecipient(item);
    toggleModal('modalReplaceRecipient')();
  };

  const onPressNotification = (item: IExtendedRecipients) => () => {
    setRecipient(item);
    toggleModal('modalNotificationRecipient')();
  };

  const renderItem = (value: IParties[]) => {
    const dataRender = getListRecipient(value);
    return (
      <View style={styles.viewListItem}>
        {dataRender.map((item, index) => {
          const historyStatus = convertHistoryStatus(item.status, item.role);
          const showAction = mappingShowHideAction(data?.status, historyStatus);
          return (
            <View key={index} style={styles.itemSigner}>
              <TouchableOpacity
                onPress={onPressRecipient(item)}
                style={styles.itemTopSigner}>
                <View style={styles.rowInfo}>
                  <View style={styles.flex}>
                    <TextCM style={styles.txtNameSigner}>
                      {item?.contact?.name}
                    </TextCM>
                  </View>
                  <TextCM
                    style={[
                      styles.txtValue,
                      {color: mappingColorHistoryStatus(historyStatus)},
                    ]}>{`• ${t(mappingRecipientToText(historyStatus))}`}</TextCM>
                </View>
                <View style={styles.rowInfo}>
                  <TextCM style={styles.txtLabelInfo}>
                    {t('eContract.DC.company')}
                  </TextCM>
                  <TextCM style={[styles.txtValue]}>{item.partyName}</TextCM>
                </View>
                <View style={styles.rowInfo}>
                  <TextCM style={styles.txtLabelInfo}>
                    {t('eContract.AI.TxtEmail')}
                  </TextCM>
                  <TextCM style={[styles.txtValue]}>
                    {item?.contact?.email}
                  </TextCM>
                </View>
                <View style={styles.rowInfo}>
                  <TextCM style={styles.txtLabelInfo}>
                    {t('eContract.AI.TxtPhone')}
                  </TextCM>
                  <TextCM style={[styles.txtValue]}>
                    {item?.contact.phone}
                  </TextCM>
                </View>
                {historyStatus === 'rejected-signing' && (
                  <View
                    style={[
                      styles.rowInfo,
                      {
                        columnGap: 8,
                      },
                    ]}>
                    <TextCM style={styles.txtLabelInfo}>
                      {t('eContract.DC.reason')}
                    </TextCM>
                    <TextCM
                      style={[
                        styles.txtValue,
                        {
                          fontFamily: Font.InterSemiBold600,
                          color: '#DA3E33',
                          flex: 1,
                        },
                      ]}>
                      {item.reason || '---'}
                    </TextCM>
                  </View>
                )}
              </TouchableOpacity>
              {(showAction.notify || showAction.replace) && !isCoordination && (
                <View style={styles.bottomItemSigner}>
                  {showAction.replace && (
                    <TouchableOpacity
                      onPress={onPressReplaceRecipient(item)}
                      style={styles.btnBottom}>
                      <IconBlueEdit width={16} height={16} />
                    </TouchableOpacity>
                  )}
                  {showAction.notify && (
                    <TouchableOpacity
                      onPress={onPressNotification(item)}
                      style={styles.btnBottom}>
                      <IconBlueRing width={16} height={16} />
                    </TouchableOpacity>
                  )}
                </View>
              )}
            </View>
          );
        })}
      </View>
    );
  };

  return (
    <SafeAreaView edges={['bottom']} style={styles.ctnMain}>
      <HeaderCM title={t('eContract.DC.TxtHistoryDocument')} />
      <ScrollView>
        <View style={styles.contain}>
          <View style={styles.body}>
            <TextCM
              style={[
                styles.txtTitle,
                data?.disableDocument &&
                  data.type === ItemType.Done &&
                  styles.txtRed,
              ]}>
              {data.name}
            </TextCM>
            <View style={styles.groupInfoDC}>
              <View style={styles.viewItem}>
                <View style={styles.viewName}>
                  <IconCreateDate width={16} height={16} />
                  <TextCM style={styles.txtName}>
                    {t('eContract.DC.TxtCreateDate')}
                  </TextCM>
                </View>
                <TextCM style={styles.txtValue}>
                  {DateUtils.convertDateToDDMMYYYY(data.createdDate)}
                </TextCM>
              </View>
              <View style={styles.viewItem}>
                <View style={styles.viewName}>
                  <IconGreyDocumentUser width={16} height={16} />
                  <TextCM style={styles.txtName}>
                    {t('eContract.DC.TxtUserCreate')}
                  </TextCM>
                </View>
                <TextCM style={styles.txtValue}>{data?.owner}</TextCM>
              </View>
              <View style={styles.viewItem}>
                <View style={styles.viewName}>
                  <IconGreyStatus width={16} height={16} />
                  <TextCM style={styles.txtName}>
                    {t('eContract.DC.status')}
                  </TextCM>
                </View>
                <View>
                  <View style={styles.reasonView}>
                    <TextCM
                      style={[
                        styles.txtValue,
                        {color: mappingColorDocumentStatus(data?.status)},
                      ]}>{`• ${t(
                      mappingDocumentStatusToText(data?.status),
                    )}`}</TextCM>
                    {data?.requester?.reason && (
                      <TextCM
                        onPress={toggleModal('modalReason')}
                        style={styles.txtReason}>
                        {`(${t('eContract.DC.reasonCancel')})`}
                      </TextCM>
                    )}
                  </View>
                </View>
              </View>
            </View>
          </View>
        </View>
        <View style={styles.sperateView} />
        <View style={styles.signedView}>
          <View style={styles.rowHeader}>
            <View style={styles.groupLeft}>
              <IconBlueListSigned width={16} height={16} />
              <TextCM style={styles.txtSigned}>
                {t('eContract.DC.listSign')}
              </TextCM>
            </View>
            <TouchableOpacity onPress={toggleModal('modalIntuitiveSigning')}>
              <TextCM style={styles.txtProcesssing}>
                {t('eContract.DC.intuitiveSigningProcess')}
              </TextCM>
            </TouchableOpacity>
          </View>
          {renderItem(data?.parties)}
        </View>
      </ScrollView>
      {showModal.modalReason && (
        <ModalReason
          onClose={toggleModal('modalReason')}
          isVisible={showModal.modalReason}
          reason={data?.requester?.reason}
        />
      )}
      {showModal.modalHistoryRecipient && (
        <ModadlHistoryRecipient
          onClose={toggleModal('modalHistoryRecipient')}
          isVisible={showModal.modalHistoryRecipient}
          documentId={data.id}
          recipientId={recipient?.id ?? ''}
          custId={data.custId}
        />
      )}
      {showModal.modalReplaceRecipient && (
        <ModalReplaceRecipient
          onClose={toggleModal('modalReplaceRecipient')}
          isVisible={showModal.modalReplaceRecipient}
          documentId={data.id}
          recipient={recipient as IExtendedRecipients}
          onFetchinng={fetchData}
        />
      )}
      {showModal.modalNotificationRecipient && (
        <ModalNotificationRecipient
          onClose={toggleModal('modalNotificationRecipient')}
          isVisible={showModal.modalNotificationRecipient}
          documentId={data.id}
          recipientId={recipient?.id ?? ''}
        />
      )}
      {showModal.modalIntuitiveSigning && (
        <ModalIntuitiveSigning
          onClose={toggleModal('modalIntuitiveSigning')}
          isVisible={showModal.modalIntuitiveSigning}
          data={data}
        />
      )}
    </SafeAreaView>
  );
};

export default DocumentHistory;
