import {
  BottomTabBarProps,
  createBottomTabNavigator,
} from '@react-navigation/bottom-tabs';
import React, {useEffect, useState} from 'react';
import {TouchableOpacity, View} from 'react-native';
import {SafeAreaView} from 'react-native-safe-area-context';
import {createNativeStackNavigator} from '@react-navigation/native-stack';
import styles from './styles';
import {useTranslation} from 'react-i18next';
import {NavigationName} from '../../constants';
import {
  IconTabDocument,
  IconTabDocumentActive,
  IconTabHome,
  IconTabHomeActive,
  IconTabNotification,
  IconTabNotificationActive,
  IconTabUser,
  IconTabUserActive,
} from '../../assets/images';
import TextCM from '../../components/Text';
import HomeScreen from '../../screens/home';
import NotificationScreen from '../../screens/notification/notification-list';
import Settings from '../../screens/settings';
import DocumentScreen from '../../screens/document/document-list';
import DocumentAuthenScreen from '../../screens/document/document-authen';

const Tab = createBottomTabNavigator();
const MyTabBar = ({state, navigation, t, badge}: any) => {
  return (
    <SafeAreaView
      edges={['right', 'bottom', 'left']}
      style={styles.ctnSafeTabBottom}>
      <View style={styles.ctnTabBottom}>
        {state.routes.map((route: any, index: any) => {
          let label = '';
          const isFocused = state.index === index;
          function getIcon() {
            switch (route.name) {
              case NavigationName.HomeScreen:
                label = t('eContract.CM.TxtTabHome');
                return (
                  <>
                    {isFocused ? (
                      <IconTabHomeActive width={23} height={20} />
                    ) : (
                      <IconTabHome width={23} height={20} />
                    )}
                  </>
                );
              case NavigationName.DocumentScreen:
                label = t('eContract.CM.TxtTabDocuments');
                return (
                  <>
                    {isFocused ? (
                      <IconTabDocumentActive width={23} height={20} />
                    ) : (
                      <IconTabDocument width={23} height={20} />
                    )}
                  </>
                );
              case NavigationName.NotificationScreen:
                label = t('eContract.CM.TxtTabNotifications');
                return (
                  <>
                    {badge > 0 && (
                      <View style={styles.ctnNoti}>
                        <TextCM style={styles.textNoti}>
                          {badge <= 99 ? badge : '99+'}
                        </TextCM>
                      </View>
                    )}
                    {isFocused ? (
                      <IconTabNotificationActive width={23} height={20} />
                    ) : (
                      <IconTabNotification width={23} height={20} />
                    )}
                  </>
                );
              case NavigationName.ProfileScreen:
                label = t('eContract.CM.TxtTabProfile');
                return (
                  <>
                    {isFocused ? (
                      <IconTabUserActive width={23} height={20} />
                    ) : (
                      <IconTabUser width={23} height={20} />
                    )}
                  </>
                );

              default:
                break;
            }
          }

          const onPress = () => {
            if (!isFocused) {
              navigation.navigate(route.name, route.params);
            }
          };

          return (
            <TouchableOpacity
              accessibilityRole="button"
              style={styles.ctnItemTabBottom}
              accessibilityState={isFocused ? {selected: true} : {}}
              key={index}
              onPress={onPress}>
              {getIcon()}
              <TextCM
                style={isFocused ? styles.txtLabelSelect : styles.txtLabel}>
                {label}
              </TextCM>
            </TouchableOpacity>
          );
        })}
      </View>
    </SafeAreaView>
  );
};

const BottomTabNavigator = () => {
  const {t} = useTranslation();
  const [badge, setBadge] = useState(0);
  // useEffect(() => {
  //   const unSub = store.subscribe(() => {
  //     setBadge(store.getState().home.data.pending);
  //     notifee.setBadgeCount(Number(store.getState().home.data.pending));
  //   });
  //   return unSub;
  // }, []);

  return (
    <>
      <Tab.Navigator
        tabBar={props => <MyTabBar {...props} t={t} totalRecoders={badge} />}
        screenOptions={{
          headerShown: false,
        }}>
        <Tab.Screen name={NavigationName.HomeScreen} component={HomeScreen} />
        <Tab.Screen
          name={NavigationName.DocumentScreen}
          component={DocumentStackScreen}
        />
        <Tab.Screen
          name={NavigationName.NotificationScreen}
          component={NotificationScreen}
        />
        <Tab.Screen name={NavigationName.ProfileScreen} component={Settings} />
      </Tab.Navigator>
    </>
  );
};

const DocumentStack = createNativeStackNavigator();
export const TabNavigate = DocumentStack.Navigator;
function DocumentStackScreen() {
  return (
    <DocumentStack.Navigator
      screenOptions={{
        headerShown: false,
        title: NavigationName.DocumentScreen,
      }}>
      <DocumentStack.Screen
        name={NavigationName.DocumentListScreen}
        component={DocumentScreen}
      />
      <DocumentStack.Screen
        name={NavigationName.DocumentVerifyScreen}
        component={DocumentAuthenScreen}
      />
    </DocumentStack.Navigator>
  );
}

export default BottomTabNavigator;
