import {TouchableOpacity} from 'react-native';
import React, {useState} from 'react';
import styles from './styles';

import {useTranslation} from 'react-i18next';
import {IGeneralSetting} from '../../../general-setting/helper';
import {getNameType} from '../../helper';
import {FilterType} from '../..';
import ModalPicType from '../ModalPicType';
import {View as ViewCM} from 'react-native';
import { IconBlackDownArrow, IconBlueBell, IconBlueIntegration, IconBlueSignature } from '../../../../../assets/images';
import { SizeDP } from '../../../../../constants/Size';
import TextCM from '../../../../../components/Text';

type Props = {
  type: IGeneralSetting;
  currentFilter: {
    label: string;
    id: FilterType;
  };
  setCurrentFilter: (filter: {label: string; id: FilterType}) => void;
  showNote?: boolean;
};

const Header = ({type, currentFilter, setCurrentFilter, showNote}: Props) => {
  const {t} = useTranslation();
  const [isVisiblePicType, setIsVisiblePicType] = useState(false);

  const togglePicType = () => {
    setIsVisiblePicType(!isVisiblePicType);
  };

  const LIST_FILTER: {
    label: string;
    id: FilterType;
  }[] = [
    {
      label: t('eContract.GS.expensesDefault.TxtIndividual'),
      id: FilterType.Individual,
    },
    {
      label: t('eContract.GS.expensesDefault.TxtCompany'),
      id: FilterType.Company,
    },
  ];

  const getIcon = () => {
    switch (type) {
      case IGeneralSetting.integration:
        return <IconBlueIntegration width={SizeDP(23)} height={SizeDP(18)} />;
      case IGeneralSetting.notification:
        return <IconBlueBell width={SizeDP(23)} height={SizeDP(18)} />;
      default:
        return <IconBlueSignature width={SizeDP(23)} height={SizeDP(18)} />;
    }
  };

  return (
    <>
      <ViewCM style={styles.header}>
        {getIcon()}
        <TextCM style={styles.txtNameType}>{t(getNameType(type))}</TextCM>
        <TouchableOpacity style={styles.btnType} onPress={togglePicType}>
          <TextCM style={styles.txtType}>{currentFilter.label}</TextCM>
          <IconBlackDownArrow width={SizeDP(10)} height={SizeDP(12)} />
        </TouchableOpacity>
      </ViewCM>
      {showNote && (
        <TextCM style={styles.txtNote}>{t('eContract.GS.expensesDefault.note')}</TextCM>
      )}
      <ModalPicType
        value={currentFilter}
        onPicType={value => {
          setCurrentFilter(value as {label: string; id: FilterType});
        }}
        lsData={LIST_FILTER}
        isVisible={isVisiblePicType}
        toggleModal={togglePicType}
      />
    </>
  );
};

export default Header;
