import React, {useEffect, useState} from 'react';
import {useTranslation} from 'react-i18next';
import {Modal, TouchableOpacity, View} from 'react-native';
import {useSafeAreaInsets} from 'react-native-safe-area-context';
import styles from './styles';
import WorkflowDiagram from './components/WorkflowDiagram';
import {IDocument} from '../../../../../model/interface/envelope.interface';
import {IcBlackLeftArrow} from '../../../../../assets/images';
import TextCM from '../../../../../components/Text';
import {DocumentStatus} from '../../../helper';
import ButtonCM from '../../../../../components/Button';
import {useDocumentServices} from '../../../../../hook/apiHook/useApi';

type Props = {
  onClose: () => void;
  isVisible: boolean;
  data: IDocument;
};

const ModalIntuitiveSigning = ({onClose, isVisible, data}: Props) => {
  const {t} = useTranslation();
  const insets = useSafeAreaInsets();
  const [dataEnvelope, setDataEnvelope] = useState<any>();

  const DocumentServices = useDocumentServices();

  useEffect(() => {
    getModelEnvenlope();
  }, []);

  const getModelEnvenlope = async () => {
    try {
      const dataResp = await DocumentServices.getModelEnvelopById(data.id);
      if (dataResp) {
        setDataEnvelope(dataResp);
      }
    } catch (error) {}
  };

  return (
    <Modal animationType="fade" transparent visible={isVisible}>
      <View style={styles.ctnContainer}>
        <View style={styles.ctnTop} onTouchEnd={onClose} />
        <View style={[styles.ctnContent, {paddingBottom: insets.bottom}]}>
          <View style={styles.viewHeader}>
            <TouchableOpacity onPress={onClose}>
              <IcBlackLeftArrow width={14} height={16} />
            </TouchableOpacity>
            <TextCM style={styles.txtTitle}>
              {t('eContract.DC.intuitiveSigningProcess')}
            </TextCM>
            <View />
          </View>
          <View style={styles.viewBody}>
            {dataEnvelope && (
              <WorkflowDiagram
                data={dataEnvelope.parties}
                status={data.status as DocumentStatus}
              />
            )}
          </View>
          <View style={styles.footer}>
            <ButtonCM onPress={onClose} label={t('eContract.CM.BtnClose')} />
          </View>
        </View>
      </View>
    </Modal>
  );
};

export default ModalIntuitiveSigning;
